from cardio_1 import a, G
# J21 — Bronchiolite aiguë · couvre J22 (P-02-Pneumologie). Rédaction Claude, 08.10.2026.
a('CFV',[('C','Commission'),('F','Fédérale pour les'),('V','Vaccinations')],'Commission fédérale pour les vaccinations','<p>Commission extraparlementaire qui élabore avec l’OFSP les recommandations du Plan de vaccination suisse, dont la prévention des infections à virus respiratoire syncytial.</p>','j21-reco-evolution')
a('PIGS',[('P','Pediatric'),('I','Infectious Disease'),('G','Group of'),('S','Switzerland')],'Groupe suisse d’infectiologie pédiatrique','<p>Groupe de travail suisse qui a coédité les consensus sur le palivizumab (2016) et le nirsévimab (2024).</p>')
a('NG9',[('NG','NICE Guideline'),('9','numéro 9')],'Recommandation NICE 9 : bronchiolite de l’enfant','<p>Recommandation britannique « Bronchiolitis in children: diagnosis and management », publiée le 1er juin 2015 et mise à jour le 9 août 2021 (seuils de saturation).</p>')
a('CG191',[('CG','Clinical Guideline (recommandation clinique NICE)'),('191','numéro 191')],'Recommandation NICE 191 : pneumonie de l’adulte','<p>Recommandation britannique sur la pneumonie de l’adulte ; elle propose des seuils de protéine C réactive pour l’antibiotique en soins primaires.</p>','j21-crp-contentieux')
a('BIDS',[('B','Bronchiolitis of'),('I','Infancy'),('D','Discharge'),('S','Study')],'Essai BIDS (étude de sortie dans la bronchiolite du nourrisson)','<p>Essai randomisé en double aveugle (Lancet 2015, 615 nourrissons) : un seuil de saturation de 90 % est aussi sûr que 94 %.</p>','j21-seuilo2')
a('PARIS',[('PARIS','Paediatric Acute respiratory Intervention Study (nom d’essai, non développé lettre à lettre)')],'Essai PARIS (oxygénothérapie à haut débit chez le nourrisson)','<p>Essai randomisé (New England Journal of Medicine 2018, 1472 nourrissons) : le haut débit réduit l’escalade thérapeutique de 23 % à 12 % hors soins intensifs.</p>','j21-hfnc')
a('MELODY',[('MELODY','nom d’essai, non développable lettre à lettre')],'Essai MELODY (nirsévimab chez l’enfant à terme et le prématuré tardif)','<p>Essai randomisé contre placebo : efficacité de 76,4 % contre les infections basses à virus respiratoire syncytial traitées médicalement et de 76,8 % contre les hospitalisations.</p>','j21-d-nirsevimab')
a('HARMONIE',[('HARMONIE','nom d’essai, non développable lettre à lettre')],'Essai HARMONIE (nirsévimab en conditions proches de la pratique)','<p>Essai ouvert chez 8057 nourrissons comparant le nirsévimab aux soins habituels : 83 % de réduction des hospitalisations à trois mois.</p>','j21-d-nirsevimab')
a('MATISSE',[('MATISSE','MATernal Immunization Study for Safety and Efficacy (nom d’essai)')],'Essai MATISSE (vaccination maternelle Abrysvo)','<p>Essai randomisé chez environ 7400 femmes enceintes (Kampmann, New England Journal of Medicine, 2023) : 82 % de réduction des infections basses graves du nourrisson à 90 jours, 69 % à 180 jours.</p>','j21-d-abrysvo')
a('MEDLEY',[('MEDLEY','nom d’essai, non développable lettre à lettre')],'Essai MEDLEY (sécurité du nirsévimab chez l’enfant à haut risque)','<p>Essai randomisé comparant le nirsévimab au palivizumab chez les grands prématurés, les cardiopathies et les maladies pulmonaires chroniques : profils de sécurité comparables.</p>','j21-d-nirsevimab')
a('IMpact-RSV',[('IMpact','nom d’essai'),('RSV','Respiratory Syncytial Virus (virus respiratoire syncytial)')],'Essai IMpact-RSV (palivizumab, 1998)','<p>Essai randomisé contre placebo chez d’anciens prématurés : hospitalisations réduites de 10,6 % à 4,8 %, efficacité de 55 %.</p>','j21-d-palivizumab')
a('IgG1',[('Ig','Immunoglobuline'),('G','de classe G'),('1','sous-classe 1')],'Immunoglobuline G de sous-classe 1','<p>Sous-classe d’IgG la plus abondante ; format du nirsévimab et de nombreux anticorps monoclonaux thérapeutiques.</p>')
a('J21.0',[('J21.0','code CIM-10-GM : J21 = bronchiolite aiguë ; .0 = due au virus respiratoire syncytial')],'Code J21.0 : bronchiolite aiguë due au virus respiratoire syncytial','<p>Utilisé lorsque le virus est identifié par un test moléculaire ou antigénique.</p>')
a('J21.1',[('J21.1','code CIM-10-GM : J21 = bronchiolite aiguë ; .1 = due au métapneumovirus humain')],'Code J21.1 : bronchiolite aiguë due au métapneumovirus humain','<p>Utilisé lorsque le métapneumovirus est identifié.</p>')
a('J21.8',[('J21.8','code CIM-10-GM : J21 = bronchiolite aiguë ; .8 = due à d’autres micro-organismes précisés')],'Code J21.8 : bronchiolite aiguë due à d’autres micro-organismes précisés','<p>Rhinovirus, virus parainfluenza, adénovirus ou autre agent identifié.</p>')
a('J21.9',[('J21.9','code CIM-10-GM : J21 = bronchiolite aiguë ; .9 = sans précision')],'Code J21.9 : bronchiolite aiguë, sans précision','<p>Bronchiolite sans agent identifié ; inclut la bronchiolite aiguë sans autre indication.</p>')
a('J06.9',[('J06.9','code CIM-10-GM : J06 = infections aiguës des voies respiratoires supérieures à localisations multiples ; .9 = sans précision')],'Code J06.9 : infection aiguë des voies respiratoires supérieures, sans précision','<p>Exclu de J22 : une infection limitée aux voies supérieures se code J06.9.</p>')
a('J98.7',[('J98.7','code CIM-10-GM : J98 = autres affections respiratoires ; .7 = infection des voies respiratoires, non classée ailleurs')],'Code J98.7 : infection des voies respiratoires sans précision de siège','<p>Exclu de J22 : il s’applique quand ni les voies supérieures ni les voies inférieures ne sont précisées.</p>')
